{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "5 <= len(s) <= 104",
      "description": "The length of the input string s is between 5 and 10,000 characters."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "k == len(possible_suffixes)",
      "description": "The output integer k is the number of distinct possible suffixes."
    },
    {
      "id": "Q2",
      "expression": "all(suffix in possible_suffixes for suffix in output_suffixes)",
      "description": "Each suffix in the output is one of the possible suffixes of the input string s."
    },
    {
      "id": "Q3",
      "expression": "output_suffixes == sorted(possible_suffixes)",
      "description": "The output suffixes are sorted in lexicographical order."
    },
    {
      "id": "Q4",
      "expression": "not any(suffix in output_suffixes for suffix in output_suffixes[1:])",
      "description": "There are no duplicate suffixes in the output."
    }
  ],
  "invariants": []
}
